import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.copy(config.position || new THREE.Vector3(0, 0, 0));
  group.rotation.order = 'YXZ';

  // Card dimensions
  const cardW = 2.4;
  const cardH = 3.2;
  const pad = 0.5;
  const headerH = 0.08;
  const lineW = 0.006;

  // Color palette
  const palette = {
    surface: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    ink: 0x16161d,
    border: 0x2a2a33,
    divider: 0x23232b,
  };

  // Card background
  const cardGeo = new THREE.PlaneGeometry(cardW, cardH);
  const cardMat = new THREE.MeshBasicMaterial({ color: palette.surface });
  const cardPlane = new THREE.Mesh(cardGeo, cardMat);
  cardPlane.position.z = 0;
  group.add(cardPlane);

  // Border frame (hairline planes)
  const borderMat = new THREE.MeshBasicMaterial({ color: palette.border });

  const topBorderGeo = new THREE.PlaneGeometry(cardW, lineW);
  const topBorder = new THREE.Mesh(topBorderGeo, borderMat);
  topBorder.position.set(0, cardH / 2 - lineW / 2, 0.001);
  group.add(topBorder);

  const bottomBorder = new THREE.Mesh(topBorderGeo, borderMat);
  bottomBorder.position.set(0, -cardH / 2 + lineW / 2, 0.001);
  group.add(bottomBorder);

  const sideBorderGeo = new THREE.PlaneGeometry(lineW, cardH);
  const leftBorder = new THREE.Mesh(sideBorderGeo, borderMat);
  leftBorder.position.set(-cardW / 2 + lineW / 2, 0, 0.001);
  group.add(leftBorder);

  const rightBorder = new THREE.Mesh(sideBorderGeo, borderMat);
  rightBorder.position.set(cardW / 2 - lineW / 2, 0, 0.001);
  group.add(rightBorder);

  // Machined metal header strip
  const headerGeo = new THREE.PlaneGeometry(cardW, headerH);
  const headerMat = new THREE.MeshStandardMaterial({
    color: 0x333333,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
  });
  const headerPlane = new THREE.Mesh(headerGeo, headerMat);
  headerPlane.position.set(0, cardH / 2 - headerH / 2, 0.002);
  group.add(headerPlane);

  // Text helper
  const textMesh = (text, font, size, weight, ls, color = palette.paper) => {
    const geom = ctx.fontAtlas.createGeometry(text, {
      fontSize: size,
      fontWeight: weight,
      family: font,
      letterSpacing: ls,
    });
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true });
    const m = new THREE.Mesh(geom, mat);
    return m;
  };

  // Tier name
  const tierMesh = textMesh('ATELIER RESERVE', 'JetBrains Mono', 20, 700, 0.08);
  tierMesh.position.set(-cardW / 2 + pad, cardH / 2 - headerH - pad, 0.003);
  tierMesh.scale.multiplyScalar(0.01);
  group.add(tierMesh);

  // Price
  const priceMesh = textMesh('$480', 'Lora', 62, 600, -0.01);
  priceMesh.position.set(-cardW / 2 + pad, cardH / 2 - headerH - pad - 0.6, 0.003);
  priceMesh.scale.multiplyScalar(0.01);
  group.add(priceMesh);

  // Caption
  const captionMesh = textMesh('PER MONTH, BILLED ANNUALLY', 'JetBrains Mono', 9, 400, 0.12);
  captionMesh.position.set(-cardW / 2 + pad, cardH / 2 - headerH - pad - 0.76, 0.003);
  captionMesh.scale.multiplyScalar(0.01);
  group.add(captionMesh);

  // Features with dividers
  const features = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing',
  ];

  const featureMeshes = [];
  features.forEach((feat, i) => {
    const fm = textMesh(feat, 'JetBrains Mono', 13, 400, 0);
    const yPos = cardH / 2 - headerH - pad - 1.2 - i * 0.4;
    fm.position.set(-cardW / 2 + pad, yPos, 0.003);
    fm.scale.multiplyScalar(0.01);
    fm.material.opacity = 0;
    group.add(fm);
    featureMeshes.push({ mesh: fm, yStart: yPos + 0.2, yEnd: yPos });

    if (i < features.length - 1) {
      const divGeo = new THREE.PlaneGeometry(cardW - 2 * pad, lineW);
      const divMat = new THREE.MeshBasicMaterial({ color: palette.divider });
      const divider = new THREE.Mesh(divGeo, divMat);
      divider.position.set(0, yPos - 0.2, 0.002);
      group.add(divider);
    }
  });

  // Gradient texture for CTA
  const gradData = new Uint8Array(256 * 3);
  for (let i = 0; i < 256; i++) {
    const t = i / 255;
    gradData[i * 3] = Math.round(255 - t * 62);
    gradData[i * 3 + 1] = Math.round(68 - t * 50);
    gradData[i * 3 + 2] = Math.round(80 - t * 49);
  }
  const gradTex = new THREE.DataTexture(gradData, 256, 1, THREE.RGBFormat);
  gradTex.needsUpdate = true;

  // CTA button
  const ctaW = 1.4;
  const ctaH = 0.36;
  const ctaY = -cardH / 2 + 0.5 + ctaH / 2;

  const ctaGeo = new THREE.PlaneGeometry(ctaW, ctaH);
  const ctaMat = new THREE.MeshBasicMaterial({
    map: gradTex,
    emissive: palette.accent,
    emissiveIntensity: 1.5,
  });
  const ctaPlane = new THREE.Mesh(ctaGeo, ctaMat);
  ctaPlane.position.set(0, ctaY, 0.004);
  group.add(ctaPlane);

  // CTA label
  const ctaLbl = textMesh('JOIN THE RESERVE', 'JetBrains Mono', 13, 700, 0.08, palette.ink);
  ctaLbl.position.set(0, ctaY, 0.005);
  ctaLbl.scale.multiplyScalar(0.01);
  group.add(ctaLbl);

  // Animations
  // Card mount: weighted-settle
  group.scale.set(1.04, 1.04, 1.04);
  gsap.to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)',
  });

  // Feature rows: fade-up with stagger
  featureMeshes.forEach((item, i) => {
    item.mesh.position.y = item.yStart;
    gsap.to(item.mesh.material, {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      delay: i * 0.08,
    });
    gsap.to(item.mesh.position, {
      y: item.yEnd,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      delay: i * 0.08,
    });
  });

  // CTA press interaction
  let ctaPressTimeline = null;
  group.userData.handlers = {
    mouseenter: () => {
      if (ctaPressTimeline) ctaPressTimeline.kill();
      ctaPressTimeline = gsap.to(ctaPlane.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
    },
    mouseleave: () => {
      if (ctaPressTimeline) ctaPressTimeline.kill();
      ctaPressTimeline = gsap.to(ctaPlane.scale, {
        x: 1, y: 1, z: 1,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
    },
  };

  // Cleanup
  group.userData.cleanup = () => {
    if (ctaPressTimeline) ctaPressTimeline.kill();
    gsap.killTweensOf([group.scale]);
    featureMeshes.forEach(item => {
      gsap.killTweensOf([item.mesh.material, item.mesh.position]);
    });
    group.traverse(child => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
    gradTex.dispose();
  };

  return group;
}
